import * as THREE from 'three/webgpu';
import { texture, uv, vec3, vec4, mix, float, uniform } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'cta-label';
  group.position.set(0, -2.85, 0.26);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 2.2;
  const height = 2.2 * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const inkColor = uniform(vec3(0x16 / 255, 0x16 / 255, 0x1d / 255));
  const surfaceColor = uniform(vec3(0x0b / 255, 0x0b / 255, 0x10 / 255));
  const accentColor = uniform(vec3(0xff / 255, 0x2a / 255, 0x38 / 255));

  const vUv = uv();
  const texSample = texture(map, vUv);

  // engineered gradient: blend surface -> ink vertically, tinted with accent at bottom edge
  const gradientMix = mix(surfaceColor, inkColor, vUv.y);
  const accentEdge = float(1.0).sub(vUv.y).pow(6.0).mul(0.35);
  const gradientWithAccent = mix(gradientMix, accentColor, accentEdge);

  const finalColor = mix(gradientWithAccent, texSample.rgb, 0.55);

  const material = new THREE.MeshBasicNodeMaterial();
  material.colorNode = vec4(finalColor, 1.0);
  material.transparent = false;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'cta-label-plane';
  group.add(plane);

  // Text: "Get started" headline
  const textMesh = createTextMesh(ctx.fontAtlas, {
    text: 'Get started',
    font: 'display',
    weight: 400,
    sizeEm: 0.34,
    color: '#e8ecf2',
    align: 'center',
    anchor: 'center'
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) {
      if (Array.isArray(textMesh.material)) {
        textMesh.material.forEach((m) => m.dispose());
      } else {
        textMesh.material.dispose();
      }
    }
  };

  return group;
}
